### Describe the feature you'd like to request

Close your eyes. **Imagine a world** where you can combine the typesafety of tRPC and the expressiveness of JSX for a heavenly API building experience. Now open your eyes. You don't have to imagine it. It's right in front of you.
```tsx
const SessionContext = createContext();
const UserContext = createContext();

const ProtectedProcedure = (props: { children: ReactNode }) => {
  const session = useContext(UserContext);

  if (!session || !session.user) {
    throw new TRPCError({ code: "UNAUTHORIZED" });
  }

  return (
    <UserContext.Provider value={session.user}>
      {props.children}
    </UserContext.Provider>
  );
};

const GreetingProcedure = () => {
  const { name } = useArgsContext();
  return `Hello ${name}`;
};

const GetUserProcedure = () => {
  const user = useContext(UserContext);

  return user;
};

const AppRouter = withTRPC(() => {
  const { req, res } = useTrpcRequestContext();
  const session = useMemo(() => getServerAuthSession(req, res), []);

  return (
    <SessionContext.Provider value={session}>
      <router>
        <query name="greeting">
          <ZodParser schema={z.object({ name: z.string() })}>
            <GreetingProcedure />
          </ZodParser>
        </query>
        <query name="getUser">
          <ProtectedProcedure>
            <GetUserProcedure />
          </ProtectedProcedure>
        </query>
      </router>
    </SessionContext.Provider>
  );
});
```

Let's break this down.

# Rendering
Each request corresponds to a render. Only those procedures requested will be run on each render.
```ts
const AppRouter = withTRPC(() => {
  // ...
});
```
The `withTRPC` function wrapper is necessary to get `req` and `res`.

# Context
All context will be done like React:
```tsx
const SessionContext = createContext();

const AppRouter = withTRPC(() => {
  const { req, res } = useTrpcRequestContext();
  const session = useMemo(() => getServerAuthSession(req, res), []);

  return (
    // session will be passed down to all procedures
    <SessionContext.Provider value={session}>
      {/* ... */}
    </SessionContext.Provider>
  );
});
```

# Middleware
React already has a composition pattern so we can just hook into that for middleware:
```ts
const ProtectedProcedure = (props: { children: ReactNode }) => {
  // session passed down from `SessionContext.Provider`
  const session = useContext(UserContext);

  // bail out if no user
  if (!session || !session.user) {
    throw new TRPCError({ code: "UNAUTHORIZED" });
  }

  return (
    <UserContext.Provider value={session.user}>
      {props.children}
    </UserContext.Provider>
  );
};
```

# Procedures
There are a few internal JSX elements for declaring procedures: `query`, `mutation`, and `subscription`, all which require the procedure name.
```ts
// this is the actual resolver for the procedure
const GreetingProcedure = () => {
  // automatically typed (call it a gift from God)
  const { name } = useArgsContext<{ name: string }>();

  return `Hello ${name}`;
};

const AppRouter = withTRPC(() => {
  return (
    <router>
      {/* this marks the procedure as a query in the router tree */}
      <query name="greeting">
        <GreetingProcedure />
      </query>
    </router>
  );
});
```

## Input Validation
```ts
const GreetingProcedure = () => {
  const { name } = useArgsContext();

  return `Hello ${name}`;
};

const AppRouter = withTRPC(() => {
  return (
    <router>
      <query name="greeting">
        {/* this parses the input data from the request and passes it on using the internal ArgsContext */}
        <ZodParser schema={z.object({ name: z.string() })}>
          <GreetingProcedure />
        </ZodParser>
      </query>
    </router>
  );
});
```


# Router
Routers and procedures can be nested like any other JSX element:
```ts
const AppRouter = withTRPC(() => {
  return (
    <router>
      <query name="greeting">
        <GreetingProcedure />
      </query>
      {/* everything under this router will be mounted at user.* */}
      <router name="user">
        {/* this mutation is mounted at user.createUser */}
        <mutation name="createUser">
          <ZodParser schema={z.object({ name: z.string(), age: z.number() })}>
            <CreateUserMutation />
          </ZodParser>
        </mutation>
      </router>
    </router>
  );
});
```

